177	#[derive(Serialize, Debug, Default)]
178	pub struct Batch {
179	    steps: Vec<BatchStep>,
180	}
181	
182	impl Batch {
183	    pub fn new() -> Self {
184	        Self { steps: Vec::new() }
185	    }
186	
187	    pub fn step(&mut self, condition: Option<BatchCond>, stmt: Stmt) {
188	        self.steps.push(BatchStep { condition, stmt });
189	    }
190	
191	    pub fn single(stmt: Stmt) -> Self {
192	        let mut batch = Batch::new();
193	        batch.step(None, stmt);
194	        batch
195	    }
196	
197	    pub(crate) fn explicit_transaction(&self) -> crate::hrana::Result<(bool, bool)> {
198	        let mut begin = false; // batch contains BEGIN transaction
199	        let mut end = false; // batch contains COMMIT/ROLLBACK
200	        for step in self.steps.iter() {
201	            if let Some(Ok(parsed)) = crate::parser::Statement::parse(&step.stmt.sql).next() {
202	                match parsed.kind {
203	                    StmtKind::TxnBegin | StmtKind::TxnBeginReadOnly => {
204	                        begin = true;
205	                        end = false;
206	                    }
207	                    StmtKind::TxnEnd => {
208	                        end = true;
209	                        begin = false;
210	                    }
211	                    _ => {}
212	                }
213	            }
214	        }
215	        Ok((begin, end))
216	    }
217	
218	    pub fn len(&self) -> usize {
219	        self.steps.len()
220	    }
221	
222	    pub fn from_iter(stmts: impl IntoIterator<Item = Stmt>, protocol_v3: bool) -> Self {
223	        let mut batch = Batch::new();
224	        let mut step = -1;
225	        for stmt in stmts.into_iter() {
226	            let cond = if step >= 0 {
227	                let mut cond = BatchCond::Ok { step };
228	                if protocol_v3 {
229	                    cond = BatchCond::And {
230	                        conds: vec![cond, BatchCond::IsAutocommit],
231	                    };
232	                }
233	                Some(cond)
234	            } else {
235	                None
236	            };
237	            batch.step(cond, stmt);
238	            step += 1;
239	        }
240	        batch
241	    }
242	}
