59	impl<S> Stream for HttpBody<S>
60	where
61	    S: Stream<Item = std::io::Result<Bytes>> + Unpin,
62	{
63	    type Item = std::io::Result<Bytes>;
64	
65	    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
66	        match self.get_mut() {
67	            HttpBody::Body(bytes) => {
68	                if let Some(bytes) = bytes.take() {
69	                    Poll::Ready(Some(Ok(bytes)))
70	                } else {
71	                    Poll::Ready(None)
72	                }
73	            }
74	            HttpBody::Stream(stream) => {
75	                let pinned = Pin::new(stream);
76	                pinned.poll_next(cx)
77	            }
78	        }
79	    }
80	}
