165	where
166	    T: HttpSend,
167	    <T as HttpSend>::Stream: Send + Sync + 'static,
168	{
169	    pub async fn query(&mut self, params: &Params) -> crate::Result<super::Rows> {
170	        let rows = self.query_raw(params).await?;
171	        Ok(super::Rows {
172	            inner: Box::new(rows),
173	        })
174	    }
