177	pub struct HranaRows<S> {
178	    cursor_step: OwnedCursorStep<S>,
179	    column_types: Option<Vec<ValueType>>,
180	}
181	
182	impl<S> HranaRows<S>
183	where
184	    S: Stream<Item = std::io::Result<Bytes>> + Unpin,
185	{
186	    async fn from_cursor(cursor: Cursor<S>) -> Result<Self> {
187	        let cursor_step = cursor.next_step_owned().await?;
188	        Ok(HranaRows {
189	            cursor_step,
190	            column_types: None,
191	        })
192	    }
193	
194	    pub async fn next(&mut self) -> crate::Result<Option<super::Row>> {
195	        let row = match self.cursor_step.next().await {
196	            Some(Ok(row)) => row,
197	            Some(Err(e)) => return Err(crate::Error::Hrana(Box::new(e))),
198	            None => return Ok(None),
199	        };
