16	        tx.execute_batch(r#"create table t(x text);"#).await?;
17	        tx.commit().await?;
18	
19	        // transaction with temporary data
20	        let tx = conn.transaction().await?;
21	        tx.execute("insert into t(x) values('hello');", ()).await?;
22	
23	        let mut rows = tx
24	            .query("select * from t where x = ?", params!["hello"])
