30	        assert!(rows.next().await?.is_none());
31	        tx.rollback().await?;
32	
33	        // confirm that temporary that was not committed
34	        let mut rows = conn
35	            .query("select * from t where x = ?", params!["hello"])
36	            .await?;
37	
38	        assert_eq!(rows.column_count(), 1);
39	        assert_eq!(rows.column_name(0), Some("x"));
40	        assert!(rows.next().await?.is_none());
41	
42	        Ok(())
43	    });
44	
45	    sim.run().unwrap();
