49	fn multiple_concurrent_transactions() {
50	    let mut sim = turmoil::Builder::new().build();
51	    sim.host("primary", super::make_standalone_server);
52	    sim.client("client", async {
53	        let db = Database::open_remote_with_connector("http://primary:8080", "", TurmoilConnector)?;
54	        let conn = db.connect()?;
55	        conn.execute_batch(r#"create table t(x text);"#).await?;
56	
57	        // open first transaction and alter data
58	        let tx1 = conn
59	            .transaction_with_behavior(TransactionBehavior::Deferred)
60	            .await?;
61	        tx1.execute("insert into t(x) values('hello');", ()).await?;
62	
63	        // while first transaction is still open open another read-only transaction and try to read
64	        let tx2 = conn
65	            .transaction_with_behavior(TransactionBehavior::ReadOnly)
66	            .await?;
67	        let mut rows = tx2
68	            .query("select * from t where x = ?", params!["hello"])
69	            .await?;
70	        assert_eq!(rows.column_count(), 1);
71	        assert_eq!(rows.column_name(0), Some("x"));
72	        assert!(rows.next().await?.is_none());
73	
74	        // commit first transaction - T2 should still read old data
75	        tx1.commit().await?;
76	
77	        let mut rows = tx2
78	            .query("select * from t where x = ?", params!["hello"])
79	            .await?;
80	        assert_eq!(rows.column_count(), 1);
81	        assert_eq!(rows.column_name(0), Some("x"));
82	        assert!(rows.next().await?.is_none());
83	        tx2.commit().await?;
84	
85	        // finally open new transaction - it now should read actual data
86	        let tx3 = conn
87	            .transaction_with_behavior(TransactionBehavior::ReadOnly)
88	            .await?;
89	        let mut rows = tx3
90	            .query("select * from t where x = ?", params!["hello"])
91	            .await?;
92	        assert_eq!(rows.column_count(), 1);
93	        assert_eq!(rows.column_name(0), Some("x"));
94	        assert_eq!(rows.next().await?.unwrap().get::<String>(0)?, "hello");
95	        assert!(rows.next().await?.is_none());
96	
97	        Ok(())
98	    });
99	    sim.run().unwrap();
100	}
